    // 根据 Name 和 RoomId 比对，把 defaultList2013 的三个字段写入 defaultList
    public static void SyncBiliUidData(List<LinkItem> targetList, List<LinkItem> sourceList2013)
    {
        if (targetList == null || sourceList2013 == null || !sourceList2013.Any())
        {
            Console.WriteLine("列表为空，跳过同步。");
            return;
        }

        // 使用 Dictionary 建立联合主键缓存 (Name + RoomId)，防止几十万条数据时嵌套循环卡死
        var sourceDict = sourceList2013
            .Where(x => !string.IsNullOrEmpty(x.Name) && !string.IsNullOrEmpty(x.RoomId))
            .GroupBy(x => new { x.Name, x.RoomId })
            .ToDictionary(
                g => g.Key,
                g => g.First() // 如果 2013 列表里有重复的 Name+RoomId，取第一个
            );

        int updatedCount = 0;

        // 遍历目标 DefaultList 进行对准填入
        foreach (var target in targetList)
        {
            var key = new { target.Name, target.RoomId };

            // 精确匹配 Name 和 RoomId
            if (sourceDict.TryGetValue(key, out var matchedSource))
            {
                // 对准填入三个字段（严格对应你 LinkItem.cs 里的实际类型）
                target.BiliUid = matchedSource.BiliUid;         // long?
                target.UidStatus = matchedSource.UidStatus;     // string?
                target.UidFetchedAt = matchedSource.UidFetchedAt; // DateTime?

                updatedCount++;
            }
        }

        Console.WriteLine($"[同步日志] 成功匹配并更新了 {updatedCount} 条主播数据。");
    }

    // 输出结果手动替换👆DefaultList
    public static void DebugSort(List<LinkItem> subsList)
    {
        //var sourceList2013 = DefaultList_2013();
        //SyncBiliUidData(subsList, sourceList2013);

        // 按 IsSubscribed 降序排序（true在前）
        var sortedList = subsList.OrderByDescending(item => item.IsSubscribed).ToList();
        int totalCount = sortedList.Count;

        // 保底备份：打印成完美对齐的 C# 代码
        Console.WriteLine("new List<LinkItem> {");

        bool hasSubscribedComment = false;
        bool hasUnsubscribedComment = false;

        for (int i = 0; i < totalCount; i++)
        {
            var item = sortedList[i];
            bool isSubscribed = item.IsSubscribed;

            // 分组注释
            if (isSubscribed && !hasSubscribedComment)
            {
                Console.WriteLine("    // 订阅的");
                hasSubscribedComment = true;
            }
            else if (!isSubscribed && !hasUnsubscribedComment)
            {
                Console.WriteLine("    // 不订阅的");
                hasUnsubscribedComment = true;
            }

            // 计算 Name 视觉宽度（中文算2，ASCII算1）
            int nameVisualWidth = item.Name.Sum(c => char.IsAscii(c) || char.IsSymbol(c) ? 1 : 2);
            int namePadding = Math.Max(0, 20 - nameVisualWidth);

            // 计算 Url 视觉宽度（这里所有Url均为ASCII，所以 len 即可）
            int urlVisualWidth = item.RoomId.Length;  // 纯ASCII，字符数=视觉宽度
            int urlPadding = Math.Max(0, 12 - urlVisualWidth);

            // 构建各部分
            string namePart = $"Name = \"{EscapeString(item.Name)}\"{new string(' ', namePadding)}";
            string urlPart = $"RoomId = \"{EscapeString(item.RoomId)}\"{new string(' ', urlPadding)}";
            string subPart = $"IsSubscribed = {isSubscribed.ToString().ToLower()}";
            string durationPart = item.Duration != 2 ? $", Duration = {item.Duration}" : "";
            string lastRecordAtPart = $"LastRecordedAt = {(item.LastRecordedAt == null ? "null" : $"DateTime.Parse({JsonSerializer.Serialize(item.LastRecordedAt)})")}";
            int lastRecordPadding = Math.Max(0, 62 - lastRecordAtPart.Length);

            string biliUidPart = $"BiliUid = {(item.BiliUid == null ? "null" : item.BiliUid)}";
            int biliUidPadding = Math.Max(0, 27 - biliUidPart.Length);

            string uidStatusPart = $"UidStatus = \"{(item.UidStatus == null ? "null" : item.UidStatus)}\"";
            int uidStatusPadding = Math.Max(0, 21 - uidStatusPart.Length);

            string UidFetchedAtPart = $"UidFetchedAt = {(item.UidFetchedAt == null ? "null" : $"DateTime.Parse({JsonSerializer.Serialize(item.UidFetchedAt)})")}";
            int fetchedPadding = Math.Max(0, 60 - UidFetchedAtPart.Length);


            // 最终 inner：Name(补齐18), Url(补齐36), IsSubscribed...
            string inner = $"{namePart}, {urlPart}, {subPart}{durationPart}, " +
                          $"{lastRecordAtPart}{new string(' ', lastRecordPadding)}, " +
                          $"{biliUidPart}{new string(' ', biliUidPadding)}, " +
                          $"{uidStatusPart}{new string(' ', uidStatusPadding)}, " +
                          $"{UidFetchedAtPart}{new string(' ', fetchedPadding)}";

            string line = $"    new LinkItem {{ {inner} }}";
            if (i < totalCount - 1) line += ",";

            Console.WriteLine(line);
        }

        // 末尾注释
        Console.WriteLine($"    //可以继续添加更多默认链接（{totalCount}）");
        Console.WriteLine("};");
    }

    // 辅助方法：转义字符串中的双引号
    static string EscapeString(string s) => s.Replace("\"", "\\\"");

    private static List<LinkItem>? _defaultList;
    private static readonly object _lock = new();

    // JSON 文件路径（推荐放在程序目录的 Data 文件夹）
    private static readonly string JsonFilePath =
        Path.Combine(AppContext.BaseDirectory, "Data", "LinkItems.json");

    // 从 JSON 文件加载
    public static List<LinkItem> Load()
    {
        try
        {
            if (!File.Exists(JsonFilePath))
            {
                // 如果文件不存在，创建空文件并返回空列表
                Directory.CreateDirectory(Path.GetDirectoryName(JsonFilePath)!);
                Save(new List<LinkItem>());
                return new List<LinkItem>();
            }

            var json = File.ReadAllText(JsonFilePath);
            var options = new JsonSerializerOptions
            {
                PropertyNameCaseInsensitive = true,
                WriteIndented = true
            };

            return JsonSerializer.Deserialize<List<LinkItem>>(json, options)
                   ?? new List<LinkItem>();
        }
        catch (Exception ex)
        {
            // 生产环境建议换成日志
            Console.WriteLine($"Load LinkItems failed: {ex.Message}");
            return new List<LinkItem>();
        }
    }

    // 保存到 JSON 文件
    public static void Save(List<LinkItem> items)
    {
        try
        {
            Directory.CreateDirectory(Path.GetDirectoryName(JsonFilePath)!);
            Console.WriteLine($"JsonFilePath: {JsonFilePath}");
            //JsonFilePath: D:\GitHub\[Workspace]\FetchVideo\Service\Service\bin\Debug\net9.0\Data\LinkItems.json

            var options = new JsonSerializerOptions
            {
                PropertyNameCaseInsensitive = true,
                WriteIndented = true,     // 格式化，便于人工查看和编辑
                Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping
            };

            var json = JsonSerializer.Serialize(items, options);
            File.WriteAllText(JsonFilePath, json);

            // 清空缓存，下次 DefaultList 会重新加载
            _defaultList = null;
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Save LinkItems failed: {ex.Message}");
            throw; // 或者根据需要处理
        }
    }

    // 可选：清空缓存，强制下次重新加载
    public static void ClearCache()
    {
        _defaultList = null;
    }
